package main
import("context";"encoding/json";"fmt";"os";"github.com/jackc/pgx/v5/pgxpool")
func main(){c:=context.Background();p,e:=pgxpool.New(c,os.Getenv("DATABASE_URL"));if e!=nil{panic(e)};defer p.Close();rows,e:=p.Query(c,`SELECT jsonb_build_object('recording',r.id,'stream',r.stream_id,'next_fire',r.next_fire_at,'job_id',j.id,'status',j.status,'fire',j.fire_at,'window_end',j.window_end_at,'owner',j.lease_owner,'lease_expires',j.lease_expires_at,'attempts',j.attempt_count,'handoff',j.handoff_owner,'clips',coalesce(cl.n,0),'first',cl.first_at,'last',cl.last_at,'bytes',coalesce(cl.bytes,0),'clip_times',cl.times,'pending_intents',coalesce(ui.pending,0),'expired_intents',coalesce(ui.expired,0),'droplet_id',d.id,'worker_build',d.build_sha,'worker_state',d.state,'node_version',n.capabilities_jsonb->>'relay_version','node_heartbeat',n.last_heartbeat_at) FROM recordings r LEFT JOIN LATERAL(SELECT * FROM recording_jobs WHERE recording_id=r.id ORDER BY fire_at DESC,id DESC LIMIT 1)j ON true LEFT JOIN LATERAL(SELECT count(*)n,min(clip_start_at)first_at,max(clip_end_at)last_at,sum(size_bytes)bytes,jsonb_agg(jsonb_build_object('start',clip_start_at,'end',clip_end_at) ORDER BY clip_start_at)filter(where clip_start_at<(j.fire_at+interval '10 minutes'))times FROM recording_clips WHERE recording_job_id=j.id)cl ON true LEFT JOIN LATERAL(SELECT count(*)filter(where status='pending')pending,count(*)filter(where status='expired')expired FROM recording_upload_intents WHERE recording_job_id=j.id)ui ON true LEFT JOIN recorder_droplets d ON d.name=j.lease_owner LEFT JOIN nodes n ON j.lease_owner='node:'||n.id::text WHERE r.id=ANY($1::bigint[]) ORDER BY r.id`,[]int64{404,380,409,379,408,410,411,412,413,414,415,416,417,418,419,420,421,422,423,424,425,426,427,428,429,430,431,432,433,434,435,436,437,438,439,440,441,442,444,445,406,401,383});if e!=nil{panic(e)};defer rows.Close();for rows.Next(){var b []byte;_ = rows.Scan(&b);var x any;_ = json.Unmarshal(b,&x);o,_:=json.Marshal(x);fmt.Println(string(o))}}
